package com.creditsense.domain;
import jakarta.persistence.*; import com.fasterxml.jackson.annotation.JsonIgnore; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="risk_assessments") public class RiskAssessment { @Id private UUID id=UUID.randomUUID(); @JsonIgnore @OneToOne @JoinColumn(name="application_id") private LoanApplication application; @Column(name="probability_of_default") private BigDecimal probabilityOfDefault; @Column(name="risk_band") private String riskBand; @Column(name="model_version") private String modelVersion; @Column(name="shap_breakdown",columnDefinition="jsonb") @org.hibernate.annotations.JdbcTypeCode(org.hibernate.type.SqlTypes.JSON) private String shapBreakdown; @Column(name="created_at") private Instant createdAt=Instant.now(); public RiskAssessment(){} public UUID getId(){return id;} public BigDecimal getProbabilityOfDefault(){return probabilityOfDefault;} public String getRiskBand(){return riskBand;} public String getModelVersion(){return modelVersion;} public String getShapBreakdown(){return shapBreakdown;} public Instant getCreatedAt(){return createdAt;} public void setApplication(LoanApplication v){application=v;} public void setProbabilityOfDefault(BigDecimal v){probabilityOfDefault=v;} public void setRiskBand(String v){riskBand=v;} public void setModelVersion(String v){modelVersion=v;} public void setShapBreakdown(String v){shapBreakdown=v;} }
